                  if (!vod_url) {

                    component.empty('No vod_url');
                    return;

                  }
                  var vod_params = _params.vod && _params.vod.params || {};

                  vod_params['_'] = Date.now();
                  vod_url = getUrlWithParams(vod_url || '/vod/' + MOVIE_ID[1], vod_params);

