UID = getStorage('uid', '');
if (!UID) {
    UID = Lampa.Utils.uid(10).toUpperCase().replace(/(.{4})/g, '$1-');
    setStorage('uid', UID);
} else if (UID.length > 12) {
    UID = UID.substring(0, 12);
    setStorage('uid', UID);
}
addSettings('title', {title: langGet('uid')});
addSettings('static', {title: UID, description: langGet('unique_id')});
